import test from "node:test";
import assert from "node:assert/strict";
import { createHash } from "node:crypto";
import { makeQR } from "../features/live/qr.js";

// Independent known matrices generated by Nayuki's Python reference, byte mode,
// M, boostecl=False, mask=0. These constants test encoding, not this implementation.
// Source: https://github.com/nayuki/QR-Code-generator/blob/master/python/qrcodegen.py
const vectors = [
  ["HELLO WORLD", 1, "2cee776cd87923a0b50751b157fe74b27d8d63df96b9e797fc0e21d47726384c"],
  ["https://www.levlab.co.kr/live?c=123456", 3, "2e5075442ccae3b757f5989adc5dba9f9da2ce1b557b7c30e4685c806c32d3a6"],
  ["가나다", 1, "09844e1239506fd584c9d14bf6caeeedbbb823c5941f83c4ade971377ff2d57e"],
  ["x".repeat(150), 8, "d04ffb513988abbe9860d07516694904bfb77e2ae758f942adbcc1de92a38c6c"],
  ["x".repeat(500), 17, "13b6e102de16ab6a4b3afe44292147ebda986af5c78dc66eb885f0a1110e6983"],
  ["x".repeat(2300), 40, "cfd522bce824b52237bfcc2c1cf07c3b0803a2e4d0f238dd81edb074b6d5ffd6"],
];
for (const [text, version, expected] of vectors) test(`QR reference matrix: ${new TextEncoder().encode(text).length} bytes / version ${version}`, () => {
  const qr = makeQR(text, { mask: 0 });
  const matrix = qr.modules.map((row) => row.map(Number).join("")).join("\n");
  assert.equal(qr.version, version);
  assert.equal(createHash("sha256").update(matrix).digest("hex"), expected);
});
test("automatic mask, quiet zone, version boundaries and capacity validation", () => {
  const qr = makeQR("https://www.levlab.co.kr/live?c=123456");
  assert.ok(qr.mask >= 0 && qr.mask < 8); assert.equal(qr.viewBox, "0 0 37 37");
  assert.ok(qr.path.startsWith("M4,4")); assert.equal(qr.version, 3);
  assert.equal(makeQR("a".repeat(14)).version, 1);
  assert.equal(makeQR("a".repeat(15)).version, 2);
  assert.throws(() => makeQR("x".repeat(2332)), RangeError);
  assert.throws(() => makeQR("ok", { mask: 9 }), RangeError);
});
